def list_level(keys, prefix):
    prefixes, objects = [], []
    for k in keys:
        if not k.startswith(prefix):
            continue
        rest = k[len(prefix):]
        if "/" in rest:
            prefixes.append(prefix + rest.split("/")[0] + "/")
        else:
            objects.append(k)
    return {"prefixes": sorted(prefixes), "objects": sorted(objects)}

coding.referenceSolution:
def list_level(keys, prefix):
    prefixes, objects = set(), []
    for k in keys:
        if not k.startswith(prefix):
            continue
        rest = k[len(prefix):]
        if "/" in rest:
            prefixes.add(prefix + rest.split("/")[0] + "/")
        else:
            objects.append(k)
    return {"prefixes": sorted(prefixes), "objects": sorted(objects)}

