from datetime import datetime, timedelta

def expires_at(query):
    signed = datetime.strptime(query["X-Amz-Date"], "%Y%m%dT%H%M%SZ")
    end = signed + timedelta(seconds=int(query["X-Amz-Expires"]))
    return end.strftime("%Y-%m-%dT%H:%M:%SZ")

