function listAllKeys(pages) {
  const keys = [];
  let page = pages.start;
  while (page.isTruncated) {
    keys.push(...page.keys);
    page = pages[page.next];
  }
  return keys;
}

coding.referenceSolution:
function listAllKeys(pages) {
  const keys = [];
  let page = pages.start;
  while (page) {
    keys.push(...page.keys.filter((k) => !k.endsWith("/")));
    page = page.isTruncated ? pages[page.next] : null;
  }
  return keys;
}

