def _match(pattern, origin):
    if pattern == "*":
        return True
    if "*" in pattern:
        pre, post = pattern.split("*", 1)
        return origin.startswith(pre) and origin.endswith(post) and len(origin) >= len(pre) + len(post)
    return pattern == origin

def cors_allows(rules, origin, method):
    for r in rules:
        if method in r["AllowedMethods"] and any(_match(p, origin) for p in r["AllowedOrigins"]):
            return True
    return False
